334: 	/*
335: 	 * We'll iterate over each canary byte per-side until fn() returns
336: 	 * false. However, we'll still iterate over the canary bytes to the
337: 	 * right of the object even if there was an error in the canary bytes to
338: 	 * the left of the object. Specifically, if check_canary_byte()
339: 	 * generates an error, showing both sides might give more clues as to
340: 	 * what the error is about when displaying which bytes were corrupted.
341: 	 */
342: 
343: 	/* Apply to left of object. */
344: 	for (addr = pageaddr; addr < meta->addr; addr++) {
345: 		if (!fn((u8 *)addr))
346: 			break;
347: 	}
348: 
349: 	/* Apply to right of object. */

410: 		meta->addr += PAGE_SIZE - size;
